using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Collections.Generic;
class IconDesigner {
 static Bitmap Draw(int size){int scale=4;Bitmap result=new Bitmap(size,size,PixelFormat.Format32bppArgb);using(Bitmap hi=new Bitmap(size*scale,size*scale,PixelFormat.Format32bppArgb)){using(Graphics g=Graphics.FromImage(hi)){g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Color.Transparent);g.ScaleTransform(size*scale/512f,size*scale/512f);RectangleF body=new RectangleF(20,20,472,472);using(Brush b=new LinearGradientBrush(body,Color.FromArgb(99,104,114),Color.FromArgb(7,9,14),60))g.FillEllipse(b,body);using(Pen p=new Pen(Color.FromArgb(140,147,160),3))g.DrawArc(p,body,192,178);RectangleF shell=new RectangleF(30,30,452,452);using(Brush b=new LinearGradientBrush(shell,Color.FromArgb(14,18,24),Color.FromArgb(39,43,52),110))g.FillEllipse(b,shell);using(Pen p=new Pen(Color.FromArgb(4,6,10),19))g.DrawEllipse(p,new RectangleF(49,49,414,414));RectangleF red=new RectangleF(57,57,398,398);int segments=size<=24?16:32;for(int i=0;i<segments;i++){float angle=-90+i*360f/segments;Color c=i<segments*3/4?Color.FromArgb(255,57,76):Color.FromArgb(182,39,59);using(Pen p=new Pen(Color.FromArgb(35,c),35))g.DrawArc(p,red,angle,360f/segments-2.2f);using(Pen p=new Pen(c,20)){p.StartCap=p.EndCap=LineCap.Flat;g.DrawArc(p,red,angle,360f/segments-3.3f);}if(size>=48)using(Pen p=new Pen(Color.FromArgb(255,151,156),3))g.DrawArc(p,RectangleF.Inflate(red,6,6),angle+1,360f/segments-6);}
 RectangleF innerRim=new RectangleF(88,88,336,336);using(Brush b=new LinearGradientBrush(innerRim,Color.FromArgb(72,79,88),Color.FromArgb(7,11,16),80))g.FillEllipse(b,innerRim);RectangleF face=new RectangleF(104,104,304,304);using(Brush b=new LinearGradientBrush(face,Color.FromArgb(24,43,43),Color.FromArgb(8,15,22),100))g.FillEllipse(b,face);Color mint=Color.FromArgb(39,246,166);using(Pen p=new Pen(Color.FromArgb(35,mint),22))g.DrawEllipse(p,RectangleF.Inflate(face,-9,-9));using(Pen p=new Pen(mint,8))g.DrawEllipse(p,RectangleF.Inflate(face,-9,-9));using(Pen p=new Pen(Color.FromArgb(83,255,200),2))g.DrawArc(p,RectangleF.Inflate(face,-16,-16),190,155);
 using(Brush b=new SolidBrush(mint)){PointF[] play={new PointF(170,211),new PointF(170,301),new PointF(243,256)};g.FillPolygon(b,play);g.FillEllipse(b,296,230,52,52);}if(size>=24)using(Pen p=new Pen(mint,7)){p.StartCap=p.EndCap=LineCap.Round;g.DrawLine(p,249,298,279,214);}}
 using(Graphics down=Graphics.FromImage(result)){down.CompositingMode=CompositingMode.SourceCopy;down.InterpolationMode=InterpolationMode.HighQualityBicubic;down.PixelOffsetMode=PixelOffsetMode.HighQuality;down.DrawImage(hi,new Rectangle(0,0,size,size),0,0,hi.Width,hi.Height,GraphicsUnit.Pixel);}}return result;}
 static void Main(){int[] sizes={16,20,24,32,40,48,64,96,128,256};List<byte[]> data=new List<byte[]>();foreach(int s in sizes)using(Bitmap b=Draw(s))using(MemoryStream m=new MemoryStream()){b.Save(m,ImageFormat.Png);data.Add(m.ToArray());}using(BinaryWriter w=new BinaryWriter(File.Create("src/app.ico"))){w.Write((ushort)0);w.Write((ushort)1);w.Write((ushort)sizes.Length);int offset=6+16*sizes.Length;for(int i=0;i<sizes.Length;i++){w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)0);w.Write((byte)0);w.Write((ushort)1);w.Write((ushort)32);w.Write(data[i].Length);w.Write(offset);offset+=data[i].Length;}foreach(byte[] d in data)w.Write(d);}using(Bitmap b=Draw(512))b.Save("assets/icon.png",ImageFormat.Png);using(Bitmap sheet=new Bitmap(560,220)){using(Graphics g=Graphics.FromImage(sheet)){g.Clear(Color.FromArgb(23,27,35));int x=15;foreach(int s in new int[]{16,24,32,48,64,128}){using(Bitmap b=Draw(s))g.DrawImageUnscaled(b,x,65-s/4);g.DrawString(s+" px",SystemFonts.MessageBoxFont,Brushes.White,x,175);x+=s+20;}}sheet.Save("docs/icon-sizes.png",ImageFormat.Png);}Console.WriteLine("Created 10 RGBA icon sizes and PNG preview");}
}
